-- UNEXECUTED / DEFAULT OFF. Normal Director/Co session only. No membership gate.
-- Reuses existing registration review + roster guards. No enrollment/payment/account/seat.
begin;
create function app.registration_resolution_enabled_v1()returns boolean language sql immutable set search_path=''as $$select false$$;
create function app.registration_resolution_actor_v1(tid uuid)returns uuid language plpgsql security definer set search_path=''set lock_timeout='250ms'as $$declare actor uuid:=auth.uid();j jsonb:=auth.jwt();begin
 if actor is null or j->>'sub'is distinct from actor::text or coalesce(j->>'role','')<>'authenticated'or coalesce(j->>'exp','')!~'^[0-9]{1,16}$'or(j->>'exp')::numeric<=extract(epoch from clock_timestamp())or coalesce(j->>'session_id','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'then return null;end if;
 perform 1 from auth.users where id=actor and deleted_at is null and(banned_until is null or banned_until<=clock_timestamp())for share nowait;if not found then return null;end if;
 perform 1 from auth.sessions where id=(j->>'session_id')::uuid and user_id=actor and(not_after is null or not_after>clock_timestamp())for share nowait;if not found then return null;end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=actor and role in('director','co_director')for share nowait;if not found then return null;end if;return actor;end$$;
create table app.registration_resolutions_v1(
 id uuid primary key,tournament_id uuid not null references app.tournaments(id),roster_entry_id uuid not null,
 actor_id uuid not null references app.profiles(id),actor_session_id uuid not null,operation_id uuid not null,receipt_id uuid not null unique references app.operation_receipts(id),
 request_payload jsonb not null,source_claim_id uuid references app.registration_claims(id),source_capture jsonb,inner_operation_id uuid not null,inner_receipt_id uuid not null references app.operation_receipts(id),response_payload jsonb not null,
 needs_resolution boolean not null default true check(needs_resolution),recorded_at timestamptz not null,
 unique(actor_id,operation_id),unique(roster_entry_id,tournament_id),unique(tournament_id,source_claim_id),foreign key(roster_entry_id,tournament_id)references app.tournament_roster_entries(id,tournament_id));
alter table app.registration_resolutions_v1 owner to postgres;
alter table app.registration_resolutions_v1 enable row level security;alter table app.registration_resolutions_v1 force row level security;
revoke all on table app.registration_resolutions_v1 from public,anon,authenticated,service_role;
create trigger registration_resolutions_immutable_v1 before update or delete on app.registration_resolutions_v1 for each row execute function app.reject_immutable_history();
create function app.registration_resolution_text_units_v1(v text)returns integer language sql immutable strict set search_path=''as $$select coalesce(sum(case when ascii(c)>65535 then 2 else 1 end),0)::integer from regexp_split_to_table(v,'')c$$;
create function app.registration_resolution_request_valid_v1(v jsonb)returns boolean language plpgsql immutable set search_path=''as $$declare d jsonb;k text;begin
 if jsonb_typeof(v)is distinct from'object'or(select count(*)from jsonb_object_keys(v))<>8 or not(v?&array['kind','mode','sourceClaim','information','errorCode','reason','reference','confirmed'])or v->>'kind'is distinct from'registration-resolution-v1'or coalesce(v->>'mode','')not in('correct_and_resubmit','override_information_review')or coalesce(v->>'errorCode','')not in('acc_lookup_unavailable','acc_not_found','information_error')or v->'confirmed'is distinct from'true'::jsonb then return false;end if;
 foreach k in array array['reason','reference']loop if jsonb_typeof(v->k)is distinct from'string'or app.registration_resolution_text_units_v1(v->>k)not between 1 and 500 or v->>k<>btrim(v->>k,U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')or v->>k~U&'[\0001-\001F\007F-\009F]'then return false;end if;end loop;
 if v->'sourceClaim'<>'null'::jsonb and(jsonb_typeof(v->'sourceClaim')is distinct from'object'or(select count(*)from jsonb_object_keys(v->'sourceClaim'))<>2 or not((v->'sourceClaim')?&array['id','digest'])or coalesce(v#>>'{sourceClaim,id}','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'or coalesce(v#>>'{sourceClaim,digest}','')!~'^[a-f0-9]{64}$')then return false;end if;
 d:=v->'information';if jsonb_typeof(d)is distinct from'object'or(select count(*)from jsonb_object_keys(d))<>5 or not(d?&array['firstName','lastName','email','accNumber','scorecardType'])then return false;end if;
 foreach k in array array['firstName','lastName','email','accNumber','scorecardType']loop if jsonb_typeof(d->k)is distinct from'string'then return false;end if;end loop;
 return app.registration_resolution_text_units_v1(trim(d->>'firstName'))between 1 and 80 and app.registration_resolution_text_units_v1(trim(d->>'lastName'))between 1 and 80 and app.registration_resolution_text_units_v1(trim(d->>'firstName')||' '||trim(d->>'lastName'))<=160 and app.registration_resolution_text_units_v1(d->>'email')<=320 and(trim(d->>'email')=''or trim(d->>'email')~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$')and app.registration_resolution_text_units_v1(d->>'accNumber')<=64 and(trim(d->>'accNumber')=''or trim(d->>'accNumber')~'^[A-Z]{2}[0-9]+Y?$')and d->>'scorecardType'in('digital','paper');end$$;
create function app.registration_resolution_claim_capture_v1(tid uuid,cid uuid)returns jsonb language sql stable security definer set search_path=''as $$select jsonb_build_object('claim',to_jsonb(c),'decision',(select to_jsonb(d)from app.registration_claim_decisions d where d.tournament_id=tid and d.claim_id=cid),'promotions',(select coalesce(jsonb_agg(r.id order by r.id),'[]')from app.tournament_roster_entries r where r.tournament_id=tid and r.source_claim_id=cid))from app.registration_claims c where c.id=cid and c.tournament_id=tid$$;
create function app.registration_resolution_receipt_v1(r app.operation_receipts,actor uuid,tid uuid,op uuid,request jsonb)returns boolean language plpgsql stable security definer set search_path=''as $$declare v jsonb:=(r).response_payload;begin
 if(r).id is null or(r).actor_profile_id<>actor or(r).tournament_id<>tid or(r).client_operation_id<>op or(r).operation_type<>'registration_resolution_v1'or(r).request_hash<>encode(extensions.digest(convert_to(jsonb_build_array('registration-resolution-v1',actor,tid,request)::text,'UTF8'),'sha256'),'hex')or v->'request'is distinct from request or v->>'actorId'<>actor::text or v->>'tournamentId'<>tid::text or v->>'operationId'<>op::text or v->'historicalReceipt'is distinct from'true'::jsonb or v->'currentRegistrationVerified'is distinct from'false'::jsonb or not exists(select 1 from app.audit_events a where a.operation_receipt_id=(r).id and a.actor_profile_id=actor and a.tournament_id=tid and a.entity_type='registration_resolution'and a.entity_id=(r).target_id and a.after_state=v)then return false;end if;
 if(r).outcome='accepted'then return v->>'status'='registration_resolution_recorded'and exists(select 1 from app.registration_resolutions_v1 x join app.operation_receipts i on i.id=x.inner_receipt_id join app.tournament_roster_entries e on e.id=x.roster_entry_id and e.tournament_id=x.tournament_id where x.receipt_id=(r).id and x.actor_id=actor and x.tournament_id=tid and x.operation_id=op and x.request_payload=request and x.response_payload=v and x.id=(r).target_id and x.roster_entry_id::text=v->>'rosterEntryId'and e.operation_receipt_id=i.id and e.creator_profile_id=actor and i.actor_profile_id=actor and i.tournament_id=tid and i.client_operation_id=x.inner_operation_id and i.outcome='accepted'and i.target_id=e.id and i.operation_type='create_manual_roster_entry_v3'and i.response_payload->>'rosterEntryId'=e.id::text);end if;
 return(r).outcome='rejected'and v->>'status'='registration_resolution_rejected'and(r).target_id=tid and v->'recordId'='null'::jsonb and v->'rosterEntryId'='null'::jsonb;end$$;
create function public.record_registration_resolution_v1(p_tournament_id uuid,p_operation_id uuid,p_request jsonb)returns jsonb language plpgsql security definer set search_path=''set lock_timeout='250ms'as $$
declare actor uuid;old app.operation_receipts%rowtype;claim app.registration_claims%rowtype;decision app.registration_claim_decisions%rowtype;entry app.tournament_roster_entries%rowtype;inner_r app.operation_receipts%rowtype;
 capture jsonb;inner_result jsonb;d jsonb:=p_request->'information';outcome jsonb;code text;rid uuid:=extensions.gen_random_uuid();record_id uuid:=extensions.gen_random_uuid();inner_op uuid:=extensions.gen_random_uuid();review_op uuid:=extensions.gen_random_uuid();stamp timestamptz:=clock_timestamp();h text;name_key text;email_key text;acc_key text;source_id uuid;inner_hash text;
begin
 if app.registration_resolution_enabled_v1()is distinct from true or current_setting('transaction_isolation')<>'read committed'or p_operation_id is null or app.registration_resolution_request_valid_v1(p_request)is distinct from true then return null;end if;
 actor:=app.registration_resolution_actor_v1(p_tournament_id);if actor is null then return null;end if;
 if not pg_try_advisory_xact_lock(hashtextextended(actor::text||':'||p_operation_id::text,0))then return jsonb_build_object('status','retry_exact','code','source_busy');end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_array('registration-resolution-v1',actor,p_tournament_id,p_request)::text,'UTF8'),'sha256'),'hex');
 select*into old from app.operation_receipts where actor_profile_id=actor and client_operation_id=p_operation_id;
 if found then if app.registration_resolution_receipt_v1(old,actor,p_tournament_id,p_operation_id,p_request)is distinct from true then return jsonb_build_object('status','blocked','code','operation_conflict');end if;return old.response_payload;end if;
 if inner_op=p_operation_id or review_op=p_operation_id or review_op=inner_op then raise exception'resolution nonce collision';end if;
 begin
  if p_request->'sourceClaim'<>'null'::jsonb then
   source_id:=(p_request#>>'{sourceClaim,id}')::uuid;
   select*into claim from app.registration_claims where id=source_id and tournament_id=p_tournament_id for update nowait;if not found then raise exception using errcode='22023',message='source_claim_unavailable';end if;
   select*into decision from app.registration_claim_decisions where claim_id=source_id and tournament_id=p_tournament_id for update nowait;
   capture:=app.registration_resolution_claim_capture_v1(p_tournament_id,source_id);
   if encode(extensions.digest(convert_to(capture::text,'UTF8'),'sha256'),'hex')is distinct from p_request#>>'{sourceClaim,digest}'then raise exception using errcode='22023',message='stale_claim';end if;
   if exists(select 1 from app.registration_resolutions_v1 where tournament_id=p_tournament_id and source_claim_id=source_id)then raise exception using errcode='22023',message='claim_already_registered';end if;
   if claim.status='withdrawn'or decision.decision='approved_for_roster'or exists(select 1 from app.tournament_roster_entries where tournament_id=p_tournament_id and source_claim_id=source_id)then raise exception using errcode='22023',message='claim_already_registered';end if;
   name_key:=lower(regexp_replace(trim(d->>'firstName')||' '||trim(d->>'lastName'),'[[:space:]]+',' ','g'));email_key:=nullif(lower(trim(d->>'email')),'');acc_key:=nullif(trim(d->>'accNumber'),'');
   code:=app.roster_identity_outcome_v1(p_tournament_id,name_key,email_key,acc_key,source_id);
   if code<>'clear'then raise exception using errcode='22023',message=case code when'duplicate'then'duplicate_roster_entry'when'withdrawn'then'withdrawn_roster_entry'else'potential_duplicate'end;end if;
   if decision.id is null then
    inner_result:=public.review_registration_claim(p_tournament_id,source_id,'rejected',null,null,'Superseded by explicit Director corrected registration: '||left(p_request->>'reason',440),review_op);
    if inner_result->>'status'is distinct from'rejected'or inner_result?'code'or not exists(select 1 from app.registration_claim_decisions where claim_id=source_id and tournament_id=p_tournament_id and id=(inner_result->>'decisionId')::uuid and decision='rejected'and actor_profile_id=actor)then raise exception using errcode='22023',message='normal_registration_rejected';end if;
   end if;
   -- Same final manual writer as v3 after its ACC/identity guard, with ONLY the explicitly superseded original excluded above.
   inner_result:=public.create_manual_roster_entry_v3_before_acc_guard(actor,p_tournament_id,d->>'firstName',d->>'lastName',d->>'email',d->>'accNumber',d->>'scorecardType',inner_op);
  else
   inner_result:=public.create_manual_roster_entry_v3(actor,p_tournament_id,d->>'firstName',d->>'lastName',d->>'email',d->>'accNumber',d->>'scorecardType',inner_op);
  end if;
  if inner_result->>'status'is distinct from'manual_roster_entry_created'then code:=coalesce(inner_result->>'code','normal_registration_rejected');if code not in('invalid_manual_entry','duplicate_roster_entry','withdrawn_roster_entry','potential_duplicate','registration_closed','initial_seating_already_published')then code:='normal_registration_rejected';end if;raise exception using errcode='22023',message=code;end if;
  select*into entry from app.tournament_roster_entries where id=(inner_result->>'rosterEntryId')::uuid and tournament_id=p_tournament_id;
  select*into inner_r from app.operation_receipts where id=entry.operation_receipt_id;
  inner_hash:=encode(extensions.digest(convert_to(jsonb_build_array('create_manual_roster_entry_v3',p_tournament_id::text,regexp_replace(trim(d->>'firstName'),'[[:space:]]+',' ','g'),regexp_replace(trim(d->>'lastName'),'[[:space:]]+',' ','g'),lower(trim(d->>'email')),trim(d->>'accNumber'),d->>'scorecardType')::text,'utf8'),'sha256'),'hex');
  if entry.id is null or inner_r.id is null or entry.creator_profile_id<>actor or entry.source_kind<>'director_manual'or inner_r.actor_profile_id<>actor or inner_r.tournament_id<>p_tournament_id or inner_r.client_operation_id<>inner_op or inner_r.operation_type<>'create_manual_roster_entry_v3'or inner_r.request_hash<>inner_hash or inner_r.target_id<>entry.id or inner_r.outcome<>'accepted'or inner_r.response_payload<>inner_result or entry.claimed_first_name<>regexp_replace(trim(d->>'firstName'),'[[:space:]]+',' ','g')or entry.claimed_last_name<>regexp_replace(trim(d->>'lastName'),'[[:space:]]+',' ','g')or coalesce(entry.claimed_email,'')<>trim(d->>'email')or coalesce(entry.claimed_acc_number,'')<>trim(d->>'accNumber')or entry.scorecard_type<>d->>'scorecardType'then raise exception'resolution inner proof failed';end if;
  if app.registration_resolution_actor_v1(p_tournament_id)is distinct from actor then raise exception'resolution authority changed';end if;
 exception when sqlstate'22023'then code:=sqlerrm;end;
 if code='clear'then code:=null;end if;
 outcome:=jsonb_build_object('status',case when code is null then'registration_resolution_recorded'else'registration_resolution_rejected'end,'actorId',actor,'tournamentId',p_tournament_id,'operationId',p_operation_id,'request',p_request,'recordId',case when code is null then record_id else null end,'rosterEntryId',case when code is null then entry.id else null end,'recordedAt',stamp,'code',coalesce(code,'registration_information_needs_resolution'),'needsResolution',code is null,'historicalReceipt',true,'currentRegistrationVerified',false,'eventEnrolled',false,'paymentRecorded',false,'checkedIn',false,'seatAssigned',false,'roleGranted',false,'membershipVerified',false,'mrpAwarded',false);
 insert into app.operation_receipts(id,tournament_id,actor_profile_id,operation_type,target_id,request_hash,client_operation_id,outcome,response_payload,applied_at)values(rid,p_tournament_id,actor,'registration_resolution_v1',case when code is null then record_id else p_tournament_id end,h,p_operation_id,case when code is null then'accepted'else'rejected'end,outcome,stamp);
 if code is null then insert into app.registration_resolutions_v1(id,tournament_id,roster_entry_id,actor_id,actor_session_id,operation_id,receipt_id,request_payload,source_claim_id,source_capture,inner_operation_id,inner_receipt_id,response_payload,recorded_at)values(record_id,p_tournament_id,entry.id,actor,(auth.jwt()->>'session_id')::uuid,p_operation_id,rid,p_request,source_id,capture,inner_op,inner_r.id,outcome,stamp);end if;
 insert into app.audit_events(tournament_id,actor_profile_id,operation_receipt_id,entity_type,entity_id,action,before_state,after_state)values(p_tournament_id,actor,rid,'registration_resolution',case when code is null then record_id else p_tournament_id end,case when code is null then'registration_completed_needs_resolution'else'registration_resolution_rejected'end,capture,outcome);
 select*into old from app.operation_receipts where id=rid;if app.registration_resolution_receipt_v1(old,actor,p_tournament_id,p_operation_id,p_request)is distinct from true then raise exception'resolution postcondition failed';end if;return outcome;
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');end$$;
create function public.get_registration_resolution_operation_v1(p_tournament_id uuid,p_operation_id uuid,p_request jsonb)returns jsonb language plpgsql security definer set search_path=''set lock_timeout='250ms'as $$declare actor uuid;r app.operation_receipts%rowtype;begin
 if app.registration_resolution_enabled_v1()is distinct from true or app.registration_resolution_request_valid_v1(p_request)is distinct from true then return null;end if;actor:=app.registration_resolution_actor_v1(p_tournament_id);if actor is null then return null;end if;
 select*into r from app.operation_receipts where actor_profile_id=actor and client_operation_id=p_operation_id;if not found then return jsonb_build_object('status','not_found','writeAuthorized',false);end if;
 if app.registration_resolution_receipt_v1(r,actor,p_tournament_id,p_operation_id,p_request)is distinct from true then return jsonb_build_object('status','blocked','code','operation_conflict');end if;return r.response_payload;
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');end$$;
create function public.get_registration_resolution_workspace_v1(p_tournament_id uuid)returns jsonb language plpgsql security definer set search_path=''set lock_timeout='250ms'as $$declare actor uuid;claims jsonb;records jsonb;begin
 if app.registration_resolution_enabled_v1()is distinct from true then return null;end if;actor:=app.registration_resolution_actor_v1(p_tournament_id);if actor is null then return null;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'digest',encode(extensions.digest(convert_to(app.registration_resolution_claim_capture_v1(p_tournament_id,c.id)::text,'UTF8'),'sha256'),'hex'),'firstName',c.first_name,'lastName',c.last_name,'displayName',c.display_name,'email',c.email,'accNumber',c.acc_number,'scorecardType',c.requested_scorecard_type,'decision',d.decision)order by c.submitted_at,c.id),'[]')into claims from app.registration_claims c left join app.registration_claim_decisions d on d.claim_id=c.id and d.tournament_id=p_tournament_id where c.tournament_id=p_tournament_id and c.status<>'withdrawn'and(d.id is null or d.decision='rejected')and not exists(select 1 from app.tournament_roster_entries r where r.tournament_id=p_tournament_id and r.source_claim_id=c.id)and not exists(select 1 from app.registration_resolutions_v1 x where x.tournament_id=p_tournament_id and x.source_claim_id=c.id);
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'rosterEntryId',x.roster_entry_id,'actorId',x.actor_id,'recordedAt',x.recorded_at,'mode',x.request_payload->>'mode','reason',x.request_payload->>'reason','reference',x.request_payload->>'reference','sourceClaimId',x.request_payload#>>'{sourceClaim,id}','needsResolution',true,'resolutionFlag','registration_information_needs_resolution')order by x.recorded_at,x.id),'[]')into records from app.registration_resolutions_v1 x where x.tournament_id=p_tournament_id;
 return jsonb_build_object('kind','registration-resolution-workspace-v1','actorId',actor,'tournamentId',p_tournament_id,'claims',claims,'records',records);
exception when lock_not_available then return null;end$$;

-- Closed deployment: no role receives EXECUTE. Future enablement is separately reviewed.
alter function app.registration_resolution_enabled_v1() owner to postgres;
revoke all on function app.registration_resolution_enabled_v1() from public,anon,authenticated,service_role;
alter function app.registration_resolution_actor_v1(uuid) owner to postgres;
revoke all on function app.registration_resolution_actor_v1(uuid) from public,anon,authenticated,service_role;
alter function app.registration_resolution_request_valid_v1(jsonb) owner to postgres;
revoke all on function app.registration_resolution_request_valid_v1(jsonb) from public,anon,authenticated,service_role;
alter function app.registration_resolution_claim_capture_v1(uuid,uuid) owner to postgres;
revoke all on function app.registration_resolution_claim_capture_v1(uuid,uuid) from public,anon,authenticated,service_role;
alter function app.registration_resolution_receipt_v1(app.operation_receipts,uuid,uuid,uuid,jsonb) owner to postgres;
revoke all on function app.registration_resolution_receipt_v1(app.operation_receipts,uuid,uuid,uuid,jsonb) from public,anon,authenticated,service_role;
alter function public.record_registration_resolution_v1(uuid,uuid,jsonb) owner to postgres;
revoke all on function public.record_registration_resolution_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;
alter function public.get_registration_resolution_operation_v1(uuid,uuid,jsonb) owner to postgres;
revoke all on function public.get_registration_resolution_operation_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;
alter function public.get_registration_resolution_workspace_v1(uuid) owner to postgres;
revoke all on function public.get_registration_resolution_workspace_v1(uuid) from public,anon,authenticated,service_role;
alter function app.registration_resolution_text_units_v1(text) owner to postgres;
revoke all on function app.registration_resolution_text_units_v1(text) from public,anon,authenticated,service_role;
commit;
